LOGO = ('<svg class="logo" viewBox="0 0 32 32" width="28" height="28" aria-hidden="true">'
        '<rect width="32" height="32" rx="8" fill="var(--accent)"/>'
        '<rect x="8" y="9" width="16" height="3" rx="1.5" fill="var(--on-accent)"/>'
        '<rect x="8" y="14.5" width="16" height="3" rx="1.5" fill="var(--on-accent)"/>'
        '<rect x="8" y="20" width="10" height="3" rx="1.5" fill="var(--on-accent)"/></svg>')


def icon(name: str, size: int = 18, cls: str = "") -> Markup:
    body = ICONS.get(name, ICONS["info"])
    return Markup(
        f'<svg class="icon {escape(cls)}" width="{int(size)}" height="{int(size)}" viewBox="0 0 24 24" fill="none" '
        f'stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" '
        f'aria-hidden="true">{body}</svg>')


def logo() -> Markup:
    return Markup(LOGO)
